import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const initialSections = {
    "SECTION 1 - PANEL": [
        { name: "Écoute active", min: 1, max: 4, description: ["distrait", "engagé"] },
        { name: "Communication orale", min: 1, max: 4, description: ["ne parle pas", "structuré/impactant"] },
        { name: "Curiosité / Esprit critique", min: 1, max: 4, description: ["aucune question", "approfondies/lien métier"] }
    ],
    "SECTION 2 - ACTIVITÉ 1 (Build Identity)": [
        { name: "Créativité", min: 1, max: 4 },
        { name: "Contribution au groupe", min: 1, max: 4 },
        { name: "Structuration des idées", min: 1, max: 4 },
        { name: "Collaboration & Teamwork", min: 1, max: 4 },
        { name: "Communication finale", min: 1, max: 4 }
    ],
    "SECTION 3 - ACTIVITÉ 2 (Fusion Challenge)": [
        { name: "Collaboration inter-équipe", min: 1, max: 4 },
        { name: "Écoute & ouverture", min: 1, max: 4 },
        { name: "Résolution de problème", min: 1, max: 4 },
        { name: "Participation & Implication", min: 1, max: 4 },
        { name: "Pitch final", min: 1, max: 4 }
    ],
    "SECTION 4 - TRANSVERSAL": [
        { name: "Leadership naturel", min: 1, max: 4 },
        { name: "Adaptabilité", min: 1, max: 4 },
        { name: "Engagement & Énergie", min: 1, max: 4 },
        { name: "Gestion du temps", min: 1, max: 4 }
    ]
};

const ManageQuestions = () => {
    const [sections, setSections] = useState(initialSections);
    const navigate = useNavigate();

    const handleAddQuestion = (sectionName) => {
        const newQuestion = { name: "Nouvelle Question", min: 1, max: 4 };
        const newSections = { ...sections };
        newSections[sectionName] = [...newSections[sectionName], newQuestion];
        setSections(newSections);
    };

    const handleDeleteQuestion = (sectionName, questionName) => {
        const newSections = { ...sections };
        newSections[sectionName] = newSections[sectionName].filter(q => q.name !== questionName);
        setSections(newSections);
    };

    const handleQuestionChange = (sectionName, oldName, newName) => {
        const newSections = { ...sections };
        const question = newSections[sectionName].find(q => q.name === oldName);
        if (question) {
            question.name = newName;
            setSections(newSections);
        }
    };

    const handleStartEvaluation = () => {
        // Save questions configuration to be used in the evaluation
        sessionStorage.setItem('evaluationQuestions', JSON.stringify(sections));
        navigate('/evaluation-simultaneous');
    };

    return (
        <div className="manage-questions-container">
            <h2>Gérer les Questions d'Évaluation</h2>
            {Object.keys(sections).map(sectionName => (
                <div key={sectionName} className="section-card">
                    <h3>{sectionName}</h3>
                    {sections[sectionName].map(q => (
                        <div key={q.name} className="question-item">
                            <input 
                                type="text" 
                                value={q.name} 
                                onChange={(e) => handleQuestionChange(sectionName, q.name, e.target.value)}
                            />
                            <button onClick={() => handleDeleteQuestion(sectionName, q.name)}>Supprimer</button>
                        </div>
                    ))}
                    <button onClick={() => handleAddQuestion(sectionName)}>Ajouter une question</button>
                </div>
            ))}
            <button onClick={handleStartEvaluation} className="next-btn">Démarrer l'évaluation</button>
        </div>
    );
};

export default ManageQuestions;
